@import url("https://fontsapi.zeoseven.com/309/main/result.css");

body {
    font-family: "KingHwaOldSong";
    font-weight: normal;
    /* font-feature-settings: "hwid"; 启用等宽变化字形 */
}

/* === 全局 UI 灰色块颜色统一修改（强力覆盖版） === */

:root {
    /* 🔧 在这里修改你想要的颜色 */
    --my-custom-ui-color: #e7f0d2; /* 示例：浅绿色，你可以改为任何颜色 */
}

/* 1. 修改思维块（思考了一会）的颜色 */
.thought-details, 
.thought-content {
    background-color: var(--my-custom-ui-color) !important;
    border-color: rgba(0,0,0,0.1) !important;
    color: #444 !important; /* 文字颜色 */
}

/* 2. 修改搜索框、标签创建框、第一条消息输入框等所有文本输入区域 */
input[type="text"], 
input[type="search"], 
textarea, 
.text_pole,
#character_description_field,
#first_mes_field {
    background-color: var(--my-custom-ui-color) !important;
    color: #2d2d2d !important;
    border: none !important;
}

/* 3. 修改设置页面中的滑动条数值块、宽度、比例等灰色背景块 */
.range-block, 
.range-block-title,
.slider-value,
.ui-slider-handle,
#movingUIPresets,
.inline-drawer-content {
    background-color: var(--my-custom-ui-color) !important;
    color: #2d2d2d !important;
}

/* 4. 针对搜索设置栏的特殊覆盖 */
#settings_search_bar,
.search_bar {
    background-color: var(--my-custom-ui-color) !important;
}

/* 5. 修改下拉菜单和选项框的背景 */
select, 
option {
    background-color: var(--my-custom-ui-color) !important;
}


/* === 引号对话块背景图（浅绿色底纹 + 透明竹子图，文字清晰可见）=== */
.mes q,
.mes .q,
.mes blockquote q {
    /* 背景图：梅花暗纹（完全透明，仅作底纹） */
    background-image: url("https://iili.io/q3pvk6F.jpg") !important;
    /* 纯色后备 + 图片叠加，用多重背景确保图片不会单独覆盖文字区 */
    background: 
        url("https://iili.io/qF340ep.jpg") no-repeat center center / cover,
        #C6DBC9 !important;  /* 图片在上，纯色在下，完全透出文字 */

    /* 混合模式：让图片变淡，纯色底色透出，文字完全不受影响 */
    background-blend-mode: overlay !important;  /* 叠加模式，图片变柔和 */

    color: #2d2d2d !important;            /* 深色文字，高可读性 */
    border-radius: 1px !important;        /* 轻微圆角 */
    padding: 4px 4px !important;          /* 内边距，让背景不贴字 */

    /* 跨行完美包裹 —— 这是您之前要求保留的核心效果 */
    box-decoration-break: clone !important;
    -webkit-box-decoration-break: clone !important;

    font-style: normal !important;
    font-weight: normal !important;
    display: inline;

    /* 为文字添加极淡阴影，在任何背景下都清晰 */
    text-shadow: 0 0 2px rgba(255,255,255,0.3) !important;
}

/* 🔧 如果图片太深影响文字，请将上面的 `overlay` 改为 `soft-light` 或 `screen`，
   或直接在 `background` 中删除图片部分，仅保留纯色。
   如需调整图片透明度，也可在 url() 后添加透明度，例如：
   linear-gradient(rgba(255,255,255,0.7), rgba(255,255,255,0.7)), url(...) */

/* === 顶部垂落树枝装饰：位置/大小/左右 全自由调节 === */
:root {
    /* ----- 树枝装饰位置控制 ----- */
    --branch-top: 67%;          /* 垂直位置：相对于顶栏底部，100%为紧贴下沿，>100%下移，<100%上移 */
    --branch-left: -15%;           /* 水平位置：0% 左对齐，50% 居中，100% 右对齐；也可用 px 精确控制 */

    /* ----- 树枝装饰尺寸控制 ----- */
    --branch-width: 85%;        /* 容器宽度（占父元素比例或固定px） */
    --branch-height:80px;      /* 容器高度（垂落长度） */

    /* ----- 背景图片控制 ----- */
    --branch-bg-size: auto 100%; /* 背景尺寸：宽度auto高度100%，可改为 contain/cover 或具体数值如 300px auto */
    --branch-bg-position: center top; /* 背景定位：水平/垂直，修改水平值可左右移动图片在容器内的位置 */
}

#top-settings-holder {
    position: relative !important; /* 作为伪元素定位基准 */
}

#top-settings-holder::before {
    content: "" !important;
    position: absolute !important;
    top: var(--branch-top) !important;
    left: var(--branch-left) !important;
    width: var(--branch-width) !important;
    height: var(--branch-height) !important;
    background-image: url("https://pic1.imgdb.cn/item/69996573d908540f9e2019ae.gif") !important;
    background-repeat: no-repeat !important;
    background-position: var(--branch-bg-position) !important;
    background-size: var(--branch-bg-size) !important;
    pointer-events: none !important;
    z-index: 999 !important;
}

/* === 仅替换明确指定的非聊天界面背景图（绝不触碰 #chat 和 .mes）=== */
:root {
    --non-chat-bg: url("https://iili.io/qFFJNVa.png");
    --non-chat-bg-repeat: no-repeat;
    --non-chat-bg-position: center center;
    --non-chat-bg-size: cover;
}

/* ===== 以下所有 ID 均独立于聊天界面，无任何误伤可能 ===== */
#WorldInfo,
#Backgrounds,
#right-nav-panel,
#left-nav-panel,
#character_popup,
#dialogue_popup,
#select_chat_popup,
#openai_api-presets,
#completion_prompt_manager,
#user-settings-block,
#rm_extensions_block,
#extensions_settings,
#extensions_settings2,
#rm_api_block,
#AdvancedFormatting,
#movingUIPresets,
 {

    background-image: var(--non-chat-bg) !important;

    background-repeat: var(--non-chat-bg-repeat) !important;

    background-position: var(--non-chat-bg-position) !important;

    background-size: var(--non-chat-bg-size) !important;

    background-color: transparent !important;

}

/* ===== 彻底不碰聊天区 ===== */
/* 没有任何规则选择 #chat、.mes 及其子元素 */

/* === 统一替换顶部所有按键图标为自定义图片（可调大小/位置）=== */
:root {
    /* ----- 顶部按键图标（预设、世界书、图库、设置等所有顶部抽屉图标）设置 ----- */
    --top-icon-width: 28px;      /* 图标宽度 */
    --top-icon-height: 28px;     /* 图标高度 */
    --top-icon-top: -10px;        /* 垂直微调：正值下移，负值上移 */
    --top-icon-left: 0px;       /* 水平微调：正值右移，负值左移 */
}

/* === 完全取消右侧灰色滚动条（隐藏所有滚动条，保留滚动功能）=== */
::-webkit-scrollbar {
    display: none !important;  /* 隐藏滚动条，但仍可滚动 */
}

/* 若只需隐藏聊天区域的垂直滚动条，改用下方代码： */
/*
#chat::-webkit-scrollbar {
    display: none !important;
}
*/

/* === 取消所有橙色元素，全部变为透明（覆盖主题色1）=== */
:root {
    --theme-color-1: transparent !important;
    --gradient-main: transparent !important;
    --top-bar-underline-color: transparent !important;
}

/* 所有引用 var(--theme-color-1) 的地方自动继承透明，无需额外规则 */

/* === 复选框选中时变为红色（包括背景、边框、勾选标记）=== */
input[type="checkbox"]:checked {
    background-color: #e7f0d2 !important;  /* 红色背景 */
    border-color: #e7f0d2 !important;      /* 红色边框 */
    box-shadow: none !important;           /* 移除原灰色边框阴影 */
}

/* 覆盖原有的橙色内阴影，改为绿色勾选标记 */
input[type="checkbox"]:checked::before {
    box-shadow: inset 1em 1em rgba(173, 213, 162, 1) !important;
}

/* 覆盖所有顶部抽屉图标（精准限定在顶栏 #top-settings-holder 内） */
#top-settings-holder .drawer-icon,


#top-settings-holder i.fa-regular,
#top-settings-holder .fa-sliders-h,      /* 预设键 */
#top-settings-holder .fa-book,           /* 世界书 */
#top-settings-holder .fa-paint-brush,    /* 背景图库 */
#top-settings-holder .fa-cog,            /* 设置 */
#top-settings-holder .fa-address-card,   /* 角色管理 */
#top-settings-holder .fa-plug,           /* 扩展 */

#top-settings-holder .fa-robot,          /* AI配置 */
#top-settings-holder .fa-arrows-alt,     /* 布局 */

#top-settings-holder .fa-question-circle /* 帮助 */ 
{
    background: url("https://iili.io/qFF2N3v.png") no-repeat center center !important;
    background-size: contain !important;
    width: var(--top-icon-width) !important;
    height: var(--top-icon-height) !important;
    font-size: 0 !important;
    color: transparent !important;
    display: inline-block !important;
    position: relative !important;
    top: var(--top-icon-top) !important;
    left: var(--top-icon-left) !important;
    background-color: transparent !important;
    border: none !important;
    box-shadow: none !important;
    text-shadow: none !important;
}



/* === 顶部按键背景图片：一张贯穿整个顶栏 === */
#top-settings-holder {
    background-image: url("https://iili.io/qFFIfCQ.jpg") !important;
    background-repeat: no-repeat !important;  /* 不重复，单张贯穿 */
    background-position: center top !important; /* 水平居中，顶部对齐 */
    background-size: cover !important;         /* 覆盖整个顶栏宽度，高度自适应 */
    background-color: transparent !important;  /* 移除原背景色 */
}

/* 确保顶栏高度能正常显示背景图（如果背景图被裁剪可调整此值） */
#top-settings-holder {
    min-height: 4px !important;  /* 请根据背景图实际高度自行调整 */
}

/* --- 纯色扁平化全局调色板 --- */
:root {
  /* 基础主色：直接提取原主题的两个核心色，改为纯色 */
  --theme-color-1: rgba(173, 213, 162, 1); /* 原引用橙 */
  --theme-color-2: rgba(173, 213, 162, 1); /* 原下划线粉 */

  /* UI 背景色：纯白与纯浅灰 */
  --ui-color-main: #ffffff;
  --ui-color-sec: #DBE5C7; 

  /* 顶栏配置：取消透明与渐变 */
  --top-bar-color: #f5f3f2;
  --top-bar-underline-color: var(--theme-color-1);
  --top-bar-icon-color: rgba(172, 214, 160, 1);

  /* 文字颜色 */
  --text-color-main: rgba(173, 213, 162, 1);
  --text-color-sec: rgba(173, 213, 162, 1);

  /* 聊天气泡颜色：纯色化 */

  --chat-background-color: #fffaf8;

  --user-color: #fffaf8;

  --char-color: #fffaf8;

  --code-color: #f8f9fa;


  /* 核心修正：将原本的渐变变量直接定义为纯色，防止其他代码失效 */
  --gradient-main: var(--theme-color-1); 
}
:root {
  --mes-width: 92%;
  /* 此百分比调整聊天气泡与整体聊天界面的距离 */
  --mes-block-width: 98%;
  /* 此百分比调整聊天记录文字与气泡左右边框的距离 */
  --box-border-radius: 1px;
  /* 所有盒子的圆角大小 */
  --top-distance: 0px;
  /* 顶栏与上边沿的距离 */
  --bottom-distance: 0px;
  /* 底栏与下边沿的距离 */
  --chat-send-spacing: 0px;
  /* 聊天界面与发送框的距离 */
  --leftRight-chat-spacing: 0px;
  /* 聊天界面与左右边沿的距离，电脑端专供 */
  --scroll-width: 5px;
  /* 滚动条宽度 */
  --icon-size: var(--mainFontSize);
  /* 图标大小 */
  --border-radius-small: 5px;
  --border-radius-medium: 10px;
  --spacing-long: 10px;
  --spacing-short: 5px;
  --topBarIconSize: calc(var(--icon-size) * 2);
}

/* 修改气泡外框 */

.mes {

    border-radius: 0px !important; /* 0px 代表绝对的直角 */

    /* 如果想要稍微有一点点弧度，可以设为 2px */

}

/* 修改文字区域（如果有背景色的话） */

.mes_text {

    border-radius: 0px !important;

}

/* ---抽屉--- */

/* 覆盖样式 */

.inline-drawer-header,

#extensions_settings .inline-drawer-toggle.inline-drawer-header,

#extensions_settings2 .inline-drawer-toggle.inline-drawer-header,

#top-settings-holder h4:not(#ai-config-button *):not(#rightNavHolder *) {

  border-width: 0 0 0 3px !important;

  border-color: transparent !important;

  border-style: solid;

  border-radius: 0;

  background-image: none !important;

  padding-left: 7px;

  border-image: linear-gradient(

      to bottom,

      transparent 25%,

      var(--theme-color-1) 25%,

      var(--theme-color-1) 75%,

      transparent 75%

    )

    1 100%;

}

/* 缩小箭头图标 */
.inline-drawer-icon {
  font-size: var(--icon-size);
}

/* 去除阴影 */

.mes_button,

.mes_edit_buttons,

#completion_prompt_manager

  #completion_prompt_manager_list

  li.completion_prompt_manager_prompt

  span

  span

  span {

  filter: none !important;

}

.fa-solid:not(#load-spinner) {

  font-size: var(--icon-size);

  text-shadow: none !important;

}
/* ---下拉框--- */

select {

  background-color: var(--ui-color-sec) !important;

  color: var(--text-color-main);

  border: none !important;

  margin: calc(var(--mainFontSize) * 0.3) 0 !important;

}

select option:not(:checked) {

  color: var(--text-color-sec);

}

select option:checked {

  color: var(--ui-color-sec);

  background-color: var(--text-color-main) !important;

}

select option {

  background-color: var(--ui-color-sec) !important;

}

.ui-widget-content .ui-state-active {

  color: var(--theme-color-1) !important;

}

/* ---勾选框--- */
input[type="checkbox"] {
  width: calc(var(--mainFontSize) * 0.9);
  height: calc(var(--mainFontSize) * 0.9);
  border: none;
  outline: none;
  background-color: var(--ui-color-main);
  filter: none;
  box-shadow: 0 0 0 1px var(--text-color-sec);
  transform: translateY(0);
  margin-left: 1px;
}

input[type="checkbox"]::before {
  box-shadow: inset 1em 1em var(--theme-color-1);
}

input[type="checkbox"].del_checkbox {
  margin-right: 0;
}

#dialogue_popup_text {
  padding: 0 var(--spacing-long) 0 0;
}

#left-nav-panel,
#right-nav-panel {
  top: var(--top-distance);
  height: 100dvh !important;
  max-height: calc(100dvh - var(--top-distance) - var(--bottom-distance) - 1px);
}

@media screen and (max-width: 1000px) {
  #left-nav-panel,
  #right-nav-panel,
  .drawer-content {
    margin-top: var(--top-distance);
  }

  #left-nav-panel,
  #right-nav-panel {
    height: calc(100dvh - 45px) !important;
    max-height: calc(100dvh - var(--topBarBlockSize)) !important;
    border-radius: 0 0 var(--border-radius-small) var(--border-radius-small);
  }
}


/* 如果你发现头像移动后背景没有跟随，或者想针对整个头像区域（包含名称）调整： */

/*

.mesAvatarWrapper {

    position: relative !important;

    top: 0px !important;

/* ---代码块--- */
code {
  margin: 0;
  border: none;
  background-color: var(--code-color);
}

body[data-stscript-style] .hljs.language-stscript,
.hljs {
  background: var(--code-color);
}

.custom-mermaid {
  background-color: var(--code-color);
}

/* 折叠框标题 */
.standoutHeader.inline-drawer-header {
  padding: 5px 0;
}
