/* =========================================
   【古风·全气泡宣纸】终极一体化方案 - 修订版
   ========================================= */

/* 1. 气泡容器：作为相对定位参考，清除自带背景图 */
.mes {
    background-color: #f7f3e8 !important; /* 宣纸基色 */
    background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='p'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.75' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23p)' opacity='0.08'/%3E%3C/svg%3E") !important; /* 仅保留纤维纹理作为背景 */
    background-repeat: repeat !important;
    background-position: center !important;
    background-size: auto !important;

    /* 气泡整体外观 */
    border: 4px solid # !important;
    border-radius: 4px !important;
    box-shadow: 0 4px 15px rgba(0,0,0,0.06), inset 0 0 60px rgba(220,200,150,0.1) !important;
    overflow: visible !important;
    margin-bottom: 20px !important;
    position: relative !important; /* 为伪元素定位 */
    z-index: 1; /* 确保文字在上层 */
}

/* 2. 用伪元素插入顶部风景图，实现完全控制 */
.mes::before {
    content: "" !important;
    position: absolute !important;
    top: 0 !important;
    left: 0 !important;
    width: 100% !important;
    height: 190px !important; /* 与您期望的图片高度一致 */
    background-image: url("https://iili.io/qFBJmzB.jpg") !important;
    background-repeat: no-repeat !important;
    background-position: top center !important;
    background-size: cover !important; /* 或 contain，根据图片比例调整 */

    /* 关键：添加底部羽化效果，让图片边缘柔和融入背景 */
    -webkit-mask-image: linear-gradient(to bottom, black 70%, transparent 100%) !important;
    mask-image: linear-gradient(to bottom, black 70%, transparent 100%) !important;

    /* 可选：降低图片不透明度，让它更像水印 */
    opacity: 0.9 !important;

    pointer-events: none !important; /* 防止遮挡交互 */
    z-index: -1; /* 置于文字下方 */

    /* 增加一点混合模式，让图片与底色相互作用 */
    mix-blend-mode: multiply !important; /* 或 overlay, soft-light 等 */
}

/* 3. 确保子元素背景透明，露出伪元素和宣纸底色 */
.mes_block, .mes_text, .ch_name, .mesAvatarWrapper {
    background: transparent !important;
    background-color: transparent !important;
    border: none !important;
    box-shadow: none !important;
    position: relative; /* 确保文字在伪元素之上（已通过z-index控制） */
    z-index: 2;
}

/* 4. 文字样式微调（可选） */
.mes_text {
    color: #2c2c2c !important;
    line-height: 1.8 !important;
    padding-bottom: 25px !important;
}


/* 在聊天气泡底部添加装饰图片 */
.mes {
    position: relative;
}
.mes::after {
    content: "";
    position: absolute;
    bottom: 0;
    left: 0;
    width: 100%;
    height: 50px; /* 可根据图片实际高度自行调整 */
    background-image: url("https://iili.io/q3pUHE7.png");
    background-repeat: no-repeat;
    background-position: bottom center;
    background-size: contain;
    pointer-events: none;
    z-index: 1;
}

