/* === 底部输入框：直角长方形 + 自定义背景图 + 尺寸/位置自由调整（变量控制） === */
:root {
    /* 整体输入框容器 (#send_form) 变量 */
    --send-form-width: 90%;            /* 宽度（px / %）*/
    --send-form-max-width: 1200px;     /* 最大宽度，防止过大 */
    --send-form-margin-top: 12px;      /* 上边距（与聊天内容的距离）*/
    --send-form-margin-bottom: 12px;   /* 下边距（与屏幕底部的距离）*/
    --send-form-padding: 8px 16px;     /* 内边距（控制背景图与内部输入框的间距）*/

    /* 内部输入框 (<textarea>) 变量 */
    --textarea-height: 30px;           /* 输入区域高度 */
    --textarea-min-height: 40px;       /* 最小高度 */
    --textarea-max-height: 200px;      /* 最大高度（自动增长时）*/
    --textarea-padding: 8px 12px;      /* 文字区域内边距 */
    --textarea-font-size: 16px;        /* 文字大小 */
}

/* —— 1. 输入框整体容器：强制直角 + 背景图 + 尺寸位置调整 —— */
#send_form {
    border-radius: 0 !important;               /* 棱角直角 */
    background-image: url("https://iili.io/qFFIfCQ.jpg") !important;
    background-size: cover !important;         /* 覆盖背景（可改为contain/具体数值）*/
    background-position: center !important;
    background-repeat: no-repeat !important;
    background-color: transparent !important;

    /* 尺寸与位置（通过变量调节）*/
    width: var(--send-form-width) !important;
    max-width: var(--send-form-max-width) !important;
    margin-top: var(--send-form-margin-top) !important;
    margin-bottom: var(--send-form-margin-bottom) !important;
    margin-left: auto !important;              /* 水平居中 */
    margin-right: auto !important;
    padding: var(--send-form-padding) !important;
    box-sizing: border-box !important;
}

/* —— 2. 输入框文字区域大小调整 —— */
#send_form textarea {
    height: var(--textarea-height) !important;
    min-height: var(--textarea-min-height) !important;
    max-height: var(--textarea-max-height) !important;
    padding: var(--textarea-padding) !important;
    font-size: var(--textarea-font-size) !important;
    background-color: rgba(255, 255, 255, 0.8) !important; /* 半透白底，提高文字可读性（可删除）*/
    border-radius: 0 !important;              /* 内部输入框也保持直角（可选）*/
}

/* —— 3. 占位符样式修改 —— */

#send_form textarea::placeholder {

    color: rgba(45, 45, 45, 0.6) !important;  /* 占位符颜色 */

    font-style: italic !important;            /* 斜体（可选）*/

    /* ⚠️ 注意：CSS 无法直接修改 placeholder 的文字内容 */

}



/* === 替换底部聊天框左侧“魔法棒”图标为自定义图片（可调大小/位置）=== */
:root {
    /* ----- 魔法棒（继续生成）图标设置 ----- */
    --magic-wand-width: 23px;
    --magic-wand-height: 23px;
    --magic-wand-top: 5px;      /* 垂直微调：正值下移，负值上移 */
    --magic-wand-left: 0px;     /* 水平微调：正值右移，负值左移 */
}

/* 覆盖所有可能的魔法棒图标类名（fa-wand-magic / fa-wand-sparkles 等） */
#send_form .fa-wand-magic,
#send_form .fa-wand-sparkles,
#send_form [class*="wand-magic"],
#send_form [class*="wand-sparkles"] {
    background: url("https://iili.io/qFFB5CP.png") no-repeat center center !important;
    background-size: contain !important;
    width: var(--magic-wand-width) !important;
    height: var(--magic-wand-height) !important;
    font-size: 0 !important;
    color: transparent !important;
    display: inline-block !important;
    position: relative !important;
    top: var(--magic-wand-top) !important;
    left: var(--magic-wand-left) !important;
    background-color: transparent !important;
    border: none !important;
    box-shadow: none !important;
}

/* 彻底移除原有图标伪元素 */
#send_form .fa-wand-magic::before,
#send_form .fa-wand-sparkles::before,
#send_form [class*="wand-magic"]::before,
#send_form [class*="wand-sparkles"]::before {
    content: none !important;
    display: none !important;
}

/* === 补充：替换底部聊天框左侧“三个横线”菜单图标为自定义图片（可调大小/位置）=== */
:root {
    /* ----- 三个横线菜单图标（如 fa-bars）设置 ----- */
    --menu-icon-width: 23px;
    --menu-icon-height: 23px;
    --menu-icon-top: 5px;      /* 垂直微调：正值下移，负值上移 */
    --menu-icon-left: -5px;     /* 水平微调：正值右移，负值左移 */
}

/* 覆盖所有可能的菜单图标类名（fa-bars / fa-hamburger / fa-menu 等） */
#send_form .fa-bars,
#send_form .fa-hamburger,
#send_form .fa-menu,
#send_form [class*="fa-bars"],
#send_form [class*="fa-hamburger"] {
    background: url("https://iili.io/qFFB5CP.png") no-repeat center center !important;
    background-size: contain !important;
    width: var(--menu-icon-width) !important;
    height: var(--menu-icon-height) !important;
    font-size: 0 !important;
    color: transparent !important;
    display: inline-block !important;
    position: relative !important;
    top: var(--menu-icon-top) !important;
    left: var(--menu-icon-left) !important;
    background-color: transparent !important;
    border: none !important;
    box-shadow: none !important;
}

/* 彻底移除原有图标伪元素 */
#send_form .fa-bars::before,
#send_form .fa-hamburger::before,
#send_form .fa-menu::before {
    content: none !important;
    display: none !important;
}

/* === 替换底部聊天框“发送键”图标为自定义图片（可调大小/位置）=== */
:root {
    /* ----- 发送键图标（如 fa-paper-plane）设置 ----- */
    --send-icon-width: 24px;
    --send-icon-height: 24px;
    --send-icon-top: 6px;      /* 垂直微调：正值下移，负值上移 */
    --send-icon-left: 0px;     /* 水平微调：正值右移，负值左移 */
}

/* 覆盖所有可能的发送键图标类名（fa-paper-plane / fa-send 等） */
#send_form .fa-paper-plane,
#send_form .fa-send,
#send_form [class*="paper-plane"],
#send_form [class*="fa-paper-plane"],
#send_form [class*="fa-send"] {
    background: url("https://iili.io/qFF5YYB.png") no-repeat center center !important;
    background-size: contain !important;
    width: var(--send-icon-width) !important;
    height: var(--send-icon-height) !important;
    font-size: 0 !important;
    color: transparent !important;
    display: inline-block !important;
    position: relative !important;
    top: var(--send-icon-top) !important;
    left: var(--send-icon-left) !important;
    background-color: transparent !important;
    border: none !important;
    box-shadow: none !important;
}

/* 彻底移除原有图标伪元素 */
#send_form .fa-paper-plane::before,
#send_form .fa-send::before,
#send_form [class*="paper-plane"]::before,
#send_form [class*="fa-paper-plane"]::before,
#send_form [class*="fa-send"]::before {
    content: none !important;
    display: none !important;
}



/* 聊天气泡内头像保留您的自定义样式 */
#chat .avatar img,

.mes .avatar img {

    position: relative !important;

    top: 98px !important;

    left: -38px !important;

    width: 54px !important;    /* 设置头像宽度 */

    height: 84px !important;   /* 设置头像高度 */

    border-radius: 0 !important;

    box-shadow: none !important;

    outline: none !important;

    border: none !important;

    background: transparent !important;

}
#chat .avatar,
.mes .avatar {
    position: relative !important;
    overflow: visible !important;
}
#chat .avatar::after,
.mes .avatar::after {
    content: "" !important;
    position: absolute !important;
    background-image: url("") !important;
    background-repeat: no-repeat !important;
    background-size: 100% 100% !important;
    pointer-events: none !important;
    z-index: 99 !important;
    top: -42px !important;
    left: -10px !important;
    width: calc(100% + 35px) !important;
    height: calc(100% + 20px) !important;
}

/* 引用块浅绿色背景 */
body .mes blockquote {
    background-color: rgba(227, 240, 212, 1) !important;
    border-left: 3px solid rgba(173, 213, 162, 1) !important;
    border-radius: 4px !important;
    padding: 4px 8px !important;
    color: # !important;
}

/* === 修复气泡水平居中偏移：移除左内边距，左右对称 === */
#chat {
    padding-left: 0 !important;
    padding-right: 0 !important;  /* 也可保留原右内边距0，但为保险两侧置0 */
}

/* --- 底栏输入框文案自定义 --- */

#nonQRFormItems {

    position: relative;

    display: flex;

    align-items: center;

}

#send_textarea::placeholder { opacity: 0 !important; color: transparent !important; }

#nonQRFormItems::before {

    content: " 春光作序";

    position: absolute;

    left: 53%;

    top: 55%;

    transform: translate(-50%, -50%);

    font-size: calc(var(--mainFontSize) * 0.95);

    color: var(--color-dark-accent) !important;

    pointer-events: none;

    z-index: 1;

    white-space: nowrap;

    transition: opacity 0.3s ease, transform 0.3s ease;

}

#nonQRFormItems:has(#send_textarea:focus)::before, #nonQRFormItems:has(#send_textarea:not(:placeholder-shown))::before {

    opacity: 0 !important;

    transform: translate(-50%, -50%) scale(0.8) !important;

}

/* === 修复输入框无法自动增高、只能显示一行的 bug === */
#send_form textarea {
    height: auto !important;          /* 解除固定高度，允许自动扩展 */
    max-height: none !important;     /* 移除最大高度限制，输入再多也全部可见，无需滑动 */
    min-height: 40px !important;     /* 保留最小高度（可按喜好调整） */
    overflow-y: hidden !important;   /* 隐藏垂直滚动条，完全靠 JS 自动增高 */
    resize: vertical;               /* 可选：允许用户手动拖拽调整高度 */
}

/* === 修复用户名字贴顶问题：统一消息容器上内边距 === */

div[is_user="true"] {

    padding-top: 85px !important;

}

/* 新增：使角色消息也有相同内边距，保证头像基准一致 */

div[is_user="false"] {

    padding-top: 85px !important;

}

/* === 强制将用户消息文字下移，角色消息不受影响 === */

div[is_user="true"] .mes_text {

    margin-top: -20px !important;      /* 外部间距，强制推下 */

    padding-top: 0 !important;        /* 清除可能的内边距干扰 */

    position: relative !important;

    top: 10px !important;            /* 额外偏移，与margin叠加，总下移50px */

}

/* 仅隐藏现实时间戳（例如“2026-02-21 5:57”），保留计时器、楼层、token */

.timestamp {

    display: none !important;

}


/* === 名字独立同步调节（防隐藏增强版） === */
:root {
    /* --- 角色 (Character) 名字偏移：调节此处修复 char 的位置 --- */
    --char-up-down: -69px;    /* 调节此值修复 {{char}} 的上下 */
    --char-left-right: 77px;   /* 调节此值修复 {{char}} 的左右 */

    /* --- 用户 (User) 名字偏移：调节此处修复 user 的位置 --- */
    --user-up-down: -69px;    /* 调节此值修复 {{user}} 的上下 */
    --user-left-right: 77px;   /* 调节此值修复 {{user}} 的左右 */

    /* --- 通用属性 --- */
    --name-font-size: 0.65em;   /* 名字大小 */
    --name-tilt: -22deg;         /* 倾斜角度 */
}

/* 1. 分别应用偏移，解决不同步问题 */

/* 针对角色消息的名字 */
div[is_user="false"] .ch_name {
    transform: translate(var(--char-left-right), var(--char-up-down)) rotate(var(--name-tilt)) !important;
}

/* 针对用户消息的名字 */
div[is_user="true"] .ch_name {
    transform: translate(var(--user-left-right), var(--user-up-down)) rotate(var(--name-tilt)) !important;
}

/* 2. 核心基础样式（保持同步） */
#chat .ch_name {
    position: relative !important;
    writing-mode: vertical-rl !important; 
    text-orientation: upright !important; 
    font-size: var(--name-font-size) !important;
    z-index: 9999 !important;      /* 强制置于最顶层 */
    display: flex !important;
    width: max-content !important;
    margin: 0 !important;
    padding: 0 !important;
    pointer-events: auto !important;
}

/* 3. 防隐藏补丁：强制父容器不裁剪溢出的内容 */
.mes, .mes_block, .mesAvatarWrapper {
    overflow: visible !important; 
}

/* 4. 兼容性修复 */
#chat .ch_name, .mes .ch_name {
    visibility: visible !important;
    opacity: 1 !important;
}

/* === 图标位置与大小全自由调节（防隐藏增强版） === */
:root {
    --icons-up-down: 110px;    /* 上下移动：建议与名字的 --name-up-down 保持一致 */
    --icons-left-right: 190px;  /* 左右移动：正数向右，负值向左（调大此值可拉开与名字的距离） */
    --icons-width-height: 20px; /* 图标大小：对应你原美化中的 20px */
}

/* 1. 核心定位代码：针对编辑铅笔和更多选项图标 */
.mes .fa-pencil, 
.mes .fa-pencil-alt, 
.mes .fa-ellipsis-h, 
.mes .fa-ellipsis,
.mes .fa-gear,
.mes .fa-cog,
.mes [class*="fa-pencil"],
.mes [class*="fa-ellipsis"] {
    position: relative !important;
    /* 使用 transform 独立移动，不触发容器裁剪，确保浮在背景图之上 */
    transform: translate(var(--icons-left-right), var(--icons-up-down)) !important;

    /* 保持原美化的显示特性，仅改变容器尺寸 */
    width: var(--icons-width-height) !important;
    height: var(--icons-width-height) !important;

    z-index: 9999 !important;      /* 强制置于最顶层，防止被背景图遮挡 */
    display: inline-block !important;
    pointer-events: auto !important;

    /* 关键修复：必须保持 font-size 为 0，否则你的自定义背景图会消失 */
    font-size: 0 !important;
    color: transparent !important;
}

/* 2. 防隐藏补丁：强制图标所在的按钮容器不裁剪溢出内容 */
.mes_buttons, .mes_edit_buttons, .mes_block, .mes {
    overflow: visible !important;
}

/* 3. 兼容性修复：确保图标可见 */
.mes .fa-pencil, .mes .fa-ellipsis-h, .mes [class*="fa-"] {
    visibility: visible !important;
    opacity: 1 !important;
}


/* === 强制全局直角化（去除所有圆角） === */

/* 1. 针对输入框、搜索栏、下拉菜单、按钮 */
input, 
select, 
textarea, 
button, 
.menu_button, 
.btn, 
.fab,
.text_pole,
#settings_search_bar,
#theme_select {
    border-radius: 0 !important;
}

/* 2. 针对设置页面中的滑动条灰色块 (Range Blocks) */
.range-block,
div.range-block,
.range-block-title {
    border-radius: 0 !important;
}

/* 3. 针对思维链（思考块）和抽屉式菜单 */
.thought-details, 
.thought-content,
.inline-drawer-header,
.inline-drawer-content,
.drawer-content {
    border-radius: 0 !important;
}

/* 4. 针对弹出层和各种容器 */
.popup, 
.list-group-item,
.character_select,
.avatar-container {
    border-radius: 0 !important;
}

/* === 彻底取消聊天气泡圆角（直角化） === */

.mes, 
.mes_block, 
.mes_text {
    /* 强制所有圆角为 0 */
    border-radius: 0 !important;

    /* 针对某些浏览器或特定主题的额外重置 */
    -webkit-border-radius: 0 !important;
    border-top-left-radius: 0 !important;
    border-top-right-radius: 0 !important;
    border-bottom-left-radius: 0 !important;
    border-bottom-right-radius: 0 !important;
}

/* 如果你使用了宣纸效果或背景图，确保伪元素也是直角 */
.mes::before, 
.mes::after {
    border-radius: 0 !important;
}

/* =========================================
   【文字高度同步调节 - 缩短与顶图距离】
   ========================================= */

:root {
    /* --- 调节此处即可缩短文字离顶部的距离 --- */
    /* 原值为 80px/85px，减小此值文字会上移，增大则下移 */
    --text-start-top: 3px; 
}

/* 1. 统一气泡内边距，确保文字起点同步 */
.mes {
    padding-top: var(--text-start-top) !important;
}

/* 2. 移除之前针对 user/char 分别设置的冲突内边距 */
div[is_user="true"], 
div[is_user="false"] {
    padding-top: var(--text-start-top) !important;
}

/* 3. 彻底消除用户消息文字的额外偏移，实现完全同步 */
div[is_user="true"] .mes_text {
    margin-top: 0 !important;
    top: 0 !important;
    position: relative !important;
}

/* 4. 确保文字块本身不带多余边距 */
.mes_text {
    padding-top: 0 !important;
}

/* 
   提示：
   - 如果觉得文字离顶图还是太远，把 --text-start-top 改小（如 40px）。
   - 如果觉得文字太靠上了，把 --text-start-top 改大（如 70px）。
   - 名字和三元素由于是绝对定位，其位置不会随此数值变动。
*/


